mini_agent.py<pre><code>"""mini_agent.py — a framework-free agent loop (AI Agents Mastery Path, Level 1)."""
import json


def call(tool_name, call_id="c1", /, **arguments):
    """Build an assistant message that requests one tool call (handy for mock models)."""
    return {"role": "assistant", "content": "",
            "tool_calls": [{"id": call_id, "name": tool_name,
                            "arguments": json.dumps(arguments)}]}


def answer(text):
    """Build an assistant message with a final answer and no tool calls."""
    return {"role": "assistant", "content": text, "tool_calls": []}


def tool_results(messages):
    """All tool results so far, decoded from JSON, oldest first."""
    return [json.loads(m["content"]) for m in messages if m["role"] == "tool"]


def print_event(event, data):
    """Default event handler: a compact, human-readable log."""
    if event == "tool_call":
        print(f"  step {data['step']}: {data['name']}({data['arguments']})")
    elif event == "tool_result":
        text = data["content"]
        print(f"      -&gt; {text[:100] + '...' if len(text) &gt; 100 else text}")
    elif event == "final":
        print(f"  step {data['step']}: final answer")
    elif event == "stopped":
        print(f"  stopped: {data['reason']}")


def execute(tools, call_):
    """Run one tool call. Never raises: problems come back as {'error': ...}."""
    fn = tools.get(call_["name"])
    if fn is None:
        return {"error": f"unknown tool '{call_['name']}'; available: {sorted(tools)}"}
    try:
        args = json.loads(call_["arguments"] or "{}")
    except json.JSONDecodeError as e:
        return {"error": f"arguments were not valid JSON ({e.msg}); resend the call"}
    try:
        return {"result": fn(**args)}
    except TypeError as e:          # missing / unexpected arguments
        return {"error": f"bad arguments: {e}"}
    except Exception as e:          # the tool itself failed
        return {"error": f"{type(e).__name__}: {e}"}


def run_agent(model, tools, task, system="You are a helpful agent. Use tools when needed.",
              max_steps=8, guards=(), on_event=print_event):
    """Run the observe-think-act loop until a final answer, a guard, or max_steps."""
    messages = [{"role": "system", "content": system},
                {"role": "user", "content": task}]
    schemas = [fn.schema for fn in tools.values()]
    state = {"messages": messages, "steps": 0, "tool_calls": 0, "errors": 0}

    for step in range(1, max_steps + 1):
        state["steps"] = step
        for guard in guards:                        # stop checks (lesson 07)
            reason = guard(state)
            if reason:
                on_event("stopped", {"step": step, "reason": reason})
                return {"answer": None, "stopped": reason, **state}

        reply = model(messages, schemas)            # THINK
        messages.append(reply)
        if not reply.get("tool_calls"):
            on_event("final", {"step": step, "content": reply["content"]})
            return {"answer": reply["content"], "stopped": None, **state}

        for c in reply["tool_calls"]:               # ACT
            state["tool_calls"] += 1
            on_event("tool_call", {"step": step, **c})
            outcome = execute(tools, c)
            if "error" in outcome:
                state["errors"] += 1
            content = json.dumps(outcome["result"] if "result" in outcome else outcome)
            on_event("tool_result", {"step": step, "id": c["id"], "content": content,
                                     "is_error": "error" in outcome})
            messages.append({"role": "tool", "tool_call_id": c["id"],
                             "content": content})   # OBSERVE on the next turn

    reason = f"step limit ({max_steps}) reached"
    on_event("stopped", {"step": max_steps, "reason": reason})
    return {"answer": None, "stopped": reason, **state}
</code></pre> <p>A few details worth noticing:</p> <ul> <li><code>execute</code> never raises. Unknown tool, broken JSON, wrong arguments and tool   crashes all become a small <code>{"error": ...}</code> object the model can read.</li> <li>Events go through <code>on_event</code>, not <code>print</code>. Lesson 09 replaces the printer with a   tracer without touching the loop.</li> <li><code>guards</code> is an empty hook for now. Lesson 07 plugs stop conditions into it.</li> <li>The return value distinguishes "answered" from "stopped", so callers never mistake a   timeout for an answer.</li> </ul>

organizer.py<pre><code>"""File-organizer agent confined to a sandbox folder (Level 1 project)."""
import json
from pathlib import Path
from tools import tool, registry
from mini_agent import run_agent
from guards import repeated_call, too_many_errors

class Sandbox:
    def __init__(self, root, dry_run=True):
        self.root = Path(root).resolve()
        self.dry_run = dry_run
        self.plan = []            # moves performed (or planned, in dry-run mode)

    def inside(self, *parts):
        """Resolve a path and refuse anything outside the sandbox root."""
        p = self.root.joinpath(*parts).resolve()
        if p != self.root and self.root not in p.parents:
            raise PermissionError(f"path '{'/'.join(parts)}' is outside the sandbox; "
                                  "use plain file and folder names only")
        return p

    def tools(self):
        box = self

        @tool
        def list_files():
            """List files (not folders) in the sandbox root with their sizes in bytes."""
            return {"files": sorted(
                [{"name": p.name, "bytes": p.stat().st_size}
                 for p in box.root.iterdir() if p.is_file()],
                key=lambda f: f["name"])}

        @tool
        def move_file(name: str, folder: str):
            """Move one file from the sandbox root into a subfolder (created if missing).
            Never overwrites. In dry-run mode, records the move without doing it.

            Args:
                name: File name exactly as returned by list_files
                folder: Destination subfolder name, e.g. 'images'
            """
            src, dest_dir = box.inside(name), box.inside(folder)
            if not src.is_file():
                raise FileNotFoundError(f"'{name}' is not a file in the sandbox root; "
                                        "call list_files to see valid names")
            dest = dest_dir / src.name
            if dest.exists():
                raise FileExistsError(f"'{folder}/{name}' already exists; skip this file")
            if not box.dry_run:
                dest_dir.mkdir(exist_ok=True)
                src.rename(dest)
            box.plan.append({"file": name, "to": folder})
            return {"moved": name, "to": folder, "dry_run": box.dry_run}

        @tool
        def finish(moved: int, skipped: str, notes: str):
            """Call once when done. Reports the number of files moved, a comma-separated
            list of skipped files, and a one-sentence note.

            Args:
                moved: Number of files moved (or planned in dry run)
                skipped: Comma-separated skipped file names, or '' if none
                notes: One sentence for the user
            """
            return {"report": {"moved": moved, "skipped": skipped, "notes": notes}}

        return registry(list_files, move_file, finish)

def ended_with_finish(state):
    """Guard: stop right after the finish tool has returned its report."""
    last = state["messages"][-1]
    if last["role"] == "tool" and '"report"' in last["content"]:
        return "finished"

def organize(model, root, dry_run=True, on_event=None, max_steps=15):
    box = Sandbox(root, dry_run)
    kwargs = {"on_event": on_event} if on_event else {}
    result = run_agent(model, box.tools(),
                       "Tidy this folder: group files into subfolders by type.",
                       max_steps=max_steps, guards=[ended_with_finish,
                       repeated_call(2), too_many_errors(3)], **kwargs)
    report = None
    for m in result["messages"]:
        if m["role"] == "tool" and '"report"' in m["content"]:
            report = json.loads(m["content"])["report"]
    return {"stopped": result["stopped"], "plan": box.plan, "report": report,
            "tool_calls": result["tool_calls"], "errors": result["errors"]}
</code></pre> <p>A few decisions to notice:</p> <ul> <li>Confinement is enforced in <code>inside()</code>, by resolving the path (which collapses <code>..</code>   and follows symlinks) and checking it is under the root. The tool description asks   for plain names, but the code is what guarantees it.</li> <li><code>finish</code> is a real tool, so its arguments are validated like any other, and the   <code>ended_with_finish</code> guard turns it into a clean stop.</li> <li>Dry run lives in the tool, not in the prompt. The model doesn't need to know or   behave differently.</li> </ul>

approval.py<pre><code>"""Wrap tools so that gated ones ask an approver before executing."""
import functools
import json

class Decision:
    def __init__(self, action, reason="", edited_args=None):
        self.action, self.reason, self.edited_args = action, reason, edited_args

def gated(needs_approval):
    """Mark a tool: needs_approval(args) -&gt; True if a human must approve these args."""
    def mark(fn):
        fn.needs_approval = needs_approval
        return fn
    return mark

def with_approvals(tools, approver, audit):
    wrapped = {}
    for name, fn in tools.items():
        check = getattr(fn, "needs_approval", None)
        if check is None:
            wrapped[name] = fn
            continue
        def make(fn=fn, name=name, check=check):
            @functools.wraps(fn)
            def inner(**args):
                if not check(args):
                    audit.append({"tool": name, "args": args, "decision": "auto"})
                    return fn(**args)
                d = approver(name, args)
                audit.append({"tool": name, "args": args, "decision": d.action,
                              "reason": d.reason, "edited_args": d.edited_args})
                if d.action == "deny":
                    return {"denied": True, "by": "human reviewer", "reason": d.reason,
                            "note": "do not retry this action; tell the user or choose "
                                    "another approach"}
                return fn(**(d.edited_args or args))
            return inner
        wrapped[name] = make()
    return wrapped
</code></pre> <p>A refund agent. Refunds of 50 or less are auto-approved by policy; larger ones go to a human. The approver here is scripted so the page's output is reproducible; in an app it would be a UI prompt, a chat message with buttons, or a ticket.</p> refund_agent.py<pre><code>import json
from tools import tool, registry
from mini_agent import run_agent, call, answer, tool_results
from approval import gated, with_approvals, Decision

@tool
def get_order(order_id: str):
    """Look up an order's amount and payment status.

    Args:
        order_id: e.g. 'A-7'
    """
    return {"A-7": {"amount": 49.0, "charged_times": 2},
            "B-9": {"amount": 640.0, "charged_times": 2}}[order_id]

@gated(lambda args: args["amount"] &gt; 50)
@tool
def issue_refund(order_id: str, amount: float, reason: str):
    """Refund money to the customer's original payment method. Irreversible.

    Args:
        order_id: Order to refund
        amount: Amount in EUR
        reason: Short reason shown on the customer's statement
    """
    return {"refunded": amount, "order_id": order_id}

def refund_model(messages, schemas):
    r = tool_results(messages)
    order_id = "A-7" if "A-7" in messages[1]["content"] else "B-9"
    if not r:
        return call("get_order", order_id=order_id)
    if len(r) == 1:
        o = r[0]
        return call("issue_refund", "c2", order_id=order_id, amount=o["amount"],
                    reason="duplicate charge")
    last = r[-1]
    if last.get("denied"):
        return answer(f"I could not refund {order_id}: a reviewer declined "
                      f"({last['reason']}). I've left the case open for the team.")
    return answer(f"Refunded {last['refunded']:.2f} EUR on {order_id}.")

def scripted_approver(tool_name, args):
    print(f"    APPROVAL NEEDED: {tool_name} {json.dumps(args)}")
    return Decision("deny", reason="amount over 500 needs finance sign-off")

audit = []
tools = with_approvals(registry(get_order, issue_refund), scripted_approver, audit)
quiet = lambda e, d: None

for task in ["Customer on order A-7 was charged twice.",
             "Customer on order B-9 was charged twice."]:
    res = run_agent(refund_model, tools, task, on_event=quiet)
    print(task, "\n  -&gt;", res["answer"])
print("audit:", json.dumps(audit, indent=1))
