multi_agent.py<pre><code>import json
from tools import tool, registry
from mini_agent import run_agent, call, answer, tool_results

quiet = lambda e, d: None
log = []                                   # (parent, child, summary) links for tracing

# ----- specialists: each is a complete agent with its own small toolset -----
@tool
def get_invoice(invoice_id: str):
    """Fetch an invoice.

    Args:
        invoice_id: e.g. 'INV-311'
    """
    return {"id": invoice_id, "amount": 49.0, "status": "paid twice"}

@tool
def track_parcel(order_id: str):
    """Tracking status for an order's parcel.

    Args:
        order_id: e.g. 'A-7'
    """
    return {"order_id": order_id, "status": "in transit", "eta": "2026-09-30"}

def billing_model(messages, schemas):
    if not tool_results(messages):
        return call("get_invoice", invoice_id="INV-311")
    inv = tool_results(messages)[-1]
    return answer(json.dumps({"finding": f"{inv['id']} was {inv['status']}",
                              "action_needed": "refund 49.00", "evidence": [inv["id"]]}))

def shipping_model(messages, schemas):
    if not tool_results(messages):
        return call("track_parcel", order_id="A-7")
    t = tool_results(messages)[-1]
    return answer(json.dumps({"finding": f"parcel {t['status']}, ETA {t['eta']}",
                              "action_needed": None, "evidence": [t["order_id"]]}))

SPECIALISTS = {"billing": (billing_model, registry(get_invoice)),
               "shipping": (shipping_model, registry(track_parcel))}

def run_specialist(name, question, max_steps=4):
    model, tools = SPECIALISTS[name]
    r = run_agent(model, tools, question, max_steps=max_steps, on_event=quiet)
    result = json.loads(r["answer"]) if r["answer"] else {"error": r["stopped"]}
    log.append(("supervisor", name, result.get("finding", result.get("error"))))
    return {**result, "steps_used": r["steps"]}

# ----- Pattern 1: supervisor, specialists exposed as tools -----
@tool
def ask_billing(question: str):
    """Delegate a billing question (invoices, charges, refunds) to the billing specialist.
    Returns finding, action_needed and evidence.

    Args:
        question: Self-contained question including any ids
    """
    return run_specialist("billing", question)

@tool
def ask_shipping(question: str):
    """Delegate a delivery question (tracking, addresses) to the shipping specialist.
    Returns finding, action_needed and evidence.

    Args:
        question: Self-contained question including any ids
    """
    return run_specialist("shipping", question)

def supervisor_model(messages, schemas):
    r = tool_results(messages)
    if len(r) == 0:
        return {"role": "assistant", "content": "Two independent questions; delegate both.",
                "tool_calls": [
                    {"id": "b", "name": "ask_billing",
                     "arguments": json.dumps({"question": "Was INV-311 charged twice?"})},
                    {"id": "s", "name": "ask_shipping",
                     "arguments": json.dumps({"question": "Where is order A-7?"})}]}
    b, s = r
    return answer(f"Billing: {b['finding']} (next: {b['action_needed']}). "
                  f"Shipping: {s['finding']}.")

print("PATTERN 1 — supervisor")
res = run_agent(supervisor_model, registry(ask_billing, ask_shipping),
                "I was charged twice on INV-311 and where is my order A-7?", on_event=quiet)
print(" ", res["answer"])
print("  supervisor context:", len(res["messages"]), "messages; links:", log)

# ----- Pattern 2: handoff, control moves to another agent -----
AGENTS = {
    "triage": "Route the user to the right specialist using transfer_to.",
    "billing": "You handle billing. Use billing tools. Speak to the user directly.",
}

@tool
def transfer_to(agent: str, summary: str):
    """Hand the conversation to another agent. Include a summary of what is known.

    Args:
        agent: 'billing' or 'shipping'
        summary: One or two sentences for the next agent
    """
    return {"transferred_to": agent}

def triage_model(messages, schemas):
    return call("transfer_to", agent="billing",
                summary="User reports a double charge on INV-311.")

def run_with_handoffs(user_msg, max_handoffs=2):
    active, history_note = "triage", ""
    for hop in range(max_handoffs + 1):
        if active == "triage":
            r = run_agent(triage_model, registry(transfer_to), user_msg,
                          system=AGENTS["triage"], max_steps=2, on_event=quiet)
            t = json.loads(r["messages"][2]["tool_calls"][0]["arguments"])
            print(f"  hop {hop}: triage -&gt; {t['agent']} with summary: {t['summary']!r}")
            active, history_note = t["agent"], t["summary"]
            continue
        task = f"[Handoff note] {history_note}\n[User] {user_msg}"
        r = run_agent(billing_model, registry(get_invoice), task,
                      system=AGENTS[active], on_event=quiet)
        print(f"  hop {hop}: {active} answered: {json.loads(r['answer'])['finding']}")
        return
    print("  too many handoffs; escalating to a human")

print("PATTERN 2 — handoff")
run_with_handoffs("Hi, I think you charged me twice for INV-311?")
</code></pre> <pre><code>PATTERN 1 — supervisor
  Billing: INV-311 was paid twice (next: refund 49.00). Shipping: parcel in transit, ETA 2026-09-30.
  supervisor context: 6 messages; links: [('supervisor', 'billing', 'INV-311 was paid twice'), ('supervisor', 'shipping', 'parcel in transit, ETA 2026-09-30')]
PATTERN 2 — handoff
  hop 0: triage -&gt; billing with summary: 'User reports a double charge on INV-311.'
  hop 1: billing answered: INV-311 was paid twice
</code></pre> <p>In pattern 1 the supervisor's context holds six messages — system, user, its delegation (two calls in one message), the two structured results, and its answer — no matter how many steps each specialist took internally. In pattern 2 the billing agent started fresh with a handoff note rather than the entire prior conversation, and <code>max_handoffs</code> bounds ping-pong.</p>

idempotency.py<pre><code>import hashlib
import json

class FlakyPaymentService:
    """Processes the refund, then 'loses' the response on the first request."""
    def __init__(self):
        self.refunds, self.seen_keys, self.requests = [], {}, 0

    def refund(self, order_id, amount, idempotency_key=None):
        self.requests += 1
        if idempotency_key and idempotency_key in self.seen_keys:
            return self.seen_keys[idempotency_key]           # replay original result
        self.refunds.append((order_id, amount))
        result = {"refund_id": f"R{len(self.refunds)}", "amount": amount}
        if idempotency_key:
            self.seen_keys[idempotency_key] = result
        if self.requests == 1:
            raise TimeoutError("response lost after processing")
        return result

def with_retries(fn, attempts=3):
    for i in range(attempts):
        try:
            return fn()
        except TimeoutError as e:
            print(f"    attempt {i + 1}: {e}; retrying")
    raise TimeoutError("gave up")

def action_key(run_id, tool, args):
    canonical = json.dumps(args, sort_keys=True)
    return hashlib.sha256(f"{run_id}|{tool}|{canonical}".encode()).hexdigest()[:16]

args = {"order_id": "A-7", "amount": 49.0}

print("naive retry:")
svc = FlakyPaymentService()
with_retries(lambda: svc.refund(**args))
print("  refunds recorded:", svc.refunds)

print("retry with idempotency key:")
svc = FlakyPaymentService()
key = action_key("run-42", "issue_refund", args)      # computed ONCE per action
r = with_retries(lambda: svc.refund(**args, idempotency_key=key))
print("  refunds recorded:", svc.refunds, "| result:", r, "| key:", key)
</code></pre> <pre><code>naive retry:
    attempt 1: response lost after processing; retrying
  refunds recorded: [('A-7', 49.0), ('A-7', 49.0)]
retry with idempotency key:
    attempt 1: response lost after processing; retrying
  refunds recorded: [('A-7', 49.0)] | result: {'refund_id': 'R1', 'amount': 49.0} | key: 91329aaacb7155b3
</code></pre> <p>The naive retry refunded twice. With the key, the second request was recognised as a repeat and returned the original result — one refund, and the agent still received a proper response.</p>

triage_system.py<pre><code>import json
import random
from tools import tool, registry
from mini_agent import run_agent, call, answer, tool_results

QUIET = lambda e, d: None

def fixture():
    return {"invoices": {"INV-1": {"amount": 20.0, "duplicate": True},
                         "INV-2": {"amount": 35.0, "duplicate": False}},
            "refunds": [], "bugs": [], "model_calls": 0, "traces": []}

def build(db, rng, p_misroute, p_skip_lookup):
    def counted(model):
        def wrapper(messages, schemas):
            db["model_calls"] += 1
            return model(messages, schemas)
        return wrapper

    # ---- billing specialist ----
    @tool
    def get_invoice(invoice_id: str):
        """Fetch an invoice's amount and whether it was charged twice.

        Args:
            invoice_id: e.g. 'INV-1'
        """
        if invoice_id not in db["invoices"]:
            raise LookupError(f"no invoice {invoice_id}")
        return {"id": invoice_id, **db["invoices"][invoice_id]}

    @tool
    def issue_refund(invoice_id: str, amount: float):
        """Refund an amount on an invoice. Irreversible.

        Args:
            invoice_id: Invoice to refund
            amount: Amount in EUR
        """
        db["refunds"].append((invoice_id, amount))
        return {"refunded": amount}

    def billing_model(messages, schemas):
        ticket = messages[1]["content"]
        inv = next((w.strip(".?!") for w in ticket.split() if w.startswith("INV-")), None)
        r = tool_results(messages)
        if not r:
            if "twice" in ticket and rng.random() &lt; p_skip_lookup:     # slip
                return call("issue_refund", "x", invoice_id=inv, amount=20.0)
            return call("get_invoice", invoice_id=inv)
        last = r[-1]
        if "error" in last:
            return answer(json.dumps({"status": "not_found", "invoice": inv}))
        if "refunded" in last:
            return answer(json.dumps({"status": "refunded", "invoice": inv}))
        if last["duplicate"]:
            return call("issue_refund", "c2", invoice_id=inv, amount=last["amount"])
        return answer(json.dumps({"status": "no_refund_due", "invoice": inv}))

    # ---- tech specialist ----
    @tool
    def search_kb(query: str):
        """Search troubleshooting articles.

        Args:
            query: Keywords
        """
        return {"articles": ["Reconnect the printer via Settings &gt; Devices"]
                if "printer" in query.lower() else []}

    @tool
    def open_bug(title: str):
        """File a bug for engineering.

        Args:
            title: Short bug title
        """
        db["bugs"].append(title)
        return {"bug_id": f"BUG-{len(db['bugs'])}"}

    def tech_model(messages, schemas):
        ticket = messages[1]["content"]
        r = tool_results(messages)
        if not r:
            return call("search_kb", query=ticket)
        if r[-1].get("articles"):
            return answer(json.dumps({"status": "self_service", "article": r[-1]["articles"][0]}))
        if "bug_id" in r[-1]:
            return answer(json.dumps({"status": "bug_filed", "bug": r[-1]["bug_id"]}))
        return call("open_bug", "c2", title=ticket[:40])

    def specialist(name, model, tools):
        def run(ticket: str):
            res = run_agent(counted(model), tools, ticket, max_steps=4, on_event=QUIET)
            db["traces"].append((name, res["messages"]))
            return json.loads(res["answer"]) if res["answer"] else {"status": "failed"}
        return run

    billing = specialist("billing", billing_model, registry(get_invoice, issue_refund))
    tech = specialist("tech", tech_model, registry(search_kb, open_bug))

    # ---- supervisor: routes, delegates, reports ----
    def supervisor(ticket):
        db["model_calls"] += 1                      # routing decision
        is_billing = "INV-" in ticket or "charge" in ticket.lower()
        if rng.random() &lt; p_misroute:               # slip
            is_billing = not is_billing
        route = "billing" if is_billing else "tech"
        result = (billing if is_billing else tech)(ticket)
        db["model_calls"] += 1                      # final summary to the user
        return route, result
    return supervisor
